sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
uniform float scale;
uniform float evolution;
uniform float complexity;
uniform float seed;
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
float vnoise(float3 p) {
    float3 i = floor(p);
    float3 f = fract(p);
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = mix(hash13(i), hash13(i + float3(1, 0, 0)), f.x);
    float b = mix(hash13(i + float3(0, 1, 0)), hash13(i + float3(1, 1, 0)), f.x);
    float c = mix(hash13(i + float3(0, 0, 1)), hash13(i + float3(1, 0, 1)), f.x);
    float d = mix(hash13(i + float3(0, 1, 1)), hash13(i + float3(1, 1, 1)), f.x);
    return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}
float fbm(float3 p, float octaves, float2 drift, float gain) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int i = 0; i < 9; i++) {
        if (float(i) >= octaves) break;
        sum += amp * vnoise(p);
        norm += amp;
        amp *= gain;
        p = float3(p.xy * 2.03 + drift + float2(17.13, 9.71), p.z * 1.7 + 3.1);
    }
    return sum / max(norm, 0.0001);
}
half4 main(float2 coord) {
    float unit = 0.4 * size.y * max(scale, 0.01);
    float2 p = (coord - size * 0.5) / unit + seed * float2(13.1, 7.7);
    float2 q = float2(fbm(float3(p, evolution), complexity, float2(0.0), 0.5), fbm(float3(p + float2(5.2, 1.3), evolution), complexity, float2(0.0), 0.5));
    float2 w = float2(fbm(float3(p + 4.0 * q + float2(1.7, 9.2), evolution * 1.3), complexity, float2(0.0), 0.5),
                      fbm(float3(p + 4.0 * q + float2(8.3, 2.8), evolution * 1.3), complexity, float2(0.0), 0.5));
    return image.eval(coord + (w - 0.5) * 2.0 * strength * unit);
}
